    ctx.lineWidth = 6;







    ctx.beginPath();







    ctx.moveTo(startX + boxW / 2, y + boxH / 2);







    ctx.lineTo(startX + (items.length - 1) * (boxW + gap) + boxW / 2, y + boxH / 2);







    ctx.stroke();







    const trackLength = (items.length - 1) * (boxW + gap);







    const activeLength = trackLength * stepProgress;







